/**
 * Unit tests for IteratorUtils.collatedIterator
 */
public class IteratorUtils_collatedIterator_TriageGen2Test {

    @Test
    public void testCollatedIteratorWithMultipleIterators() {
        Comparator<Integer> comparator = Integer::compare;

        List<Integer> list1 = Arrays.asList(1, 5, 10);
        List<Integer> list2 = Arrays.asList(2, 4, 8);
        List<Integer> list3 = Arrays.asList(3, 6, 7);

        Collection<Iterator<? extends Integer>> iterators = new ArrayList<>();
        iterators.add(list1.iterator());
        iterators.add(list2.iterator());
        iterators.add(list3.iterator());

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iterators);

        List<Integer> expected = Arrays.asList(1, 2, 3, 4, 5, 6, 7, 8, 10);
        List<Integer> actual = new ArrayList<>();
        while (result.hasNext()) {
            actual.add(result.next());
        }

        assertEquals("The collated iterator should return elements in sorted order across all iterators", expected, actual);
    }












}

